package com.nthexperience.desktop;
import android.app.*;import android.content.*;import android.content.pm.*;import android.net.Uri;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;import java.util.function.Consumer;
/** In-shell composition and drafts. The chosen mail application owns inbox, authentication and final sending. */
final class EightMail extends LinearLayout {
    static final int PICK=8604;final Activity activity;final DesktopStore store;final Consumer<String> open;final FrameLayout content;final LinearLayout form;final Map<String,EditText> fields=new LinkedHashMap<>();final TextView status;final List<Uri> attachments=new ArrayList<>();String id=UUID.randomUUID().toString();boolean listing;
    EightMail(Activity a,DesktopStore s,Consumer<String> open){super(a);setSaveFromParentEnabled(false);activity=a;store=s;this.open=open;setOrientation(VERTICAL);setBackgroundColor(0xfffafafa);setContentDescription("Eight Mail");TenAppearance.preserve(this);EightAppUi.bar(a,this,"Mail",0xff0078a4);LinearLayout bar=EightAppUi.commands(a,this);bar.addView(EightAppUi.button(a,"New message",()->{if(keep()){clear();compose();}}));bar.addView(EightAppUi.button(a,"Drafts",()->{if(keep())drafts();}));bar.addView(EightAppUi.button(a,"Inbox in mail app",this::inbox));bar.addView(EightAppUi.button(a,"Choose mail app",this::chooseApp));bar.addView(EightAppUi.button(a,"Webmail",this::webmail));status=EightAppUi.text(a,"Compose here. Your email app handles accounts, inbox and final sending.",13);status.setPadding(Aero.dp(a,14),Aero.dp(a,7),Aero.dp(a,14),Aero.dp(a,7));addView(status);content=new FrameLayout(a);addView(content,new LayoutParams(-1,0,1));form=EightAppUi.dialogBody(a);for(String[] f:new String[][]{{"to","To"},{"cc","Cc"},{"bcc","Bcc"},{"subject","Subject"},{"body","Message"}}){EditText value=EightAppUi.input(a,form,f[1],!f[0].equals("body"));value.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(f[0].equals("body")?16384:f[0].equals("subject")?512:2048)});if(Arrays.asList("to","cc","bcc").contains(f[0]))value.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS);fields.put(f[0],value);}LinearLayout actions=EightAppUi.commands(a,form);actions.addView(EightAppUi.button(a,"People",()->{if(keep())open.accept("@people");}));actions.addView(EightAppUi.button(a,"Attach files",this::pick));actions.addView(EightAppUi.button(a,"Clear attachments",()->{attachments.clear();attachmentStatus();}));actions.addView(EightAppUi.button(a,"Save draft",()->save(true)));actions.addView(EightAppUi.button(a,"Send with email app",this::send));compose();}
    JSONObject draft(){JSONObject row=new JSONObject();GadgetLayout.put(row,"id",id);for(Map.Entry<String,EditText> f:fields.entrySet())GadgetLayout.put(row,f.getKey(),f.getValue().getText().toString());JSONArray links=new JSONArray();for(Uri u:attachments)links.put(u.toString());GadgetLayout.put(row,"attachments",links);return row;}
    boolean nonempty(){for(EditText value:fields.values())if(value.length()>0)return true;return !attachments.isEmpty();}
    boolean keep(){return !nonempty()||save(false);}
    boolean save(boolean feedback){try{EightPimStore.save(store,EightPimModels.DRAFTS,draft());if(feedback)status.setText("Draft saved locally. It has not been sent.");return true;}catch(JSONException e){EightAppUi.error(activity,e);return false;}}
    void clear(){id=UUID.randomUUID().toString();for(EditText value:fields.values())value.setText("");attachments.clear();attachmentStatus();}
    void compose(){listing=false;content.removeAllViews();if(form.getParent() instanceof ViewGroup)((ViewGroup)form.getParent()).removeView(form);content.addView(EightAppUi.scroll(activity,form),new FrameLayout.LayoutParams(-1,-1));}
    void composeTo(String address){if(!keep())return;clear();fields.get("to").setText(address);compose();fields.get("subject").requestFocus();}
    void drafts(){listing=true;content.removeAllViews();JSONArray rows=EightPimStore.rows(store,EightPimModels.DRAFTS);List<JSONObject> drafts=new ArrayList<>();List<String> labels=new ArrayList<>();for(int i=rows.length()-1;i>=0;i--){JSONObject p=rows.optJSONObject(i);if(p==null)continue;drafts.add(p);labels.add((p.optString("subject").isEmpty()?"Untitled message":p.optString("subject"))+"\nTo: "+p.optString("to"));}if(drafts.isEmpty()){TextView empty=EightAppUi.text(activity,"No saved drafts. Choose New message to compose.",16);empty.setPadding(Aero.dp(activity,20),Aero.dp(activity,20),Aero.dp(activity,20),0);content.addView(empty);return;}ListView list=EightAppUi.list(activity,labels,n->{if(!keep())return;load(drafts.get(n));compose();});list.setContentDescription("Mail drafts");list.setOnItemLongClickListener((parent,v,n,rowId)->{JSONObject p=drafts.get(n);Aero.dialog(activity).setTitle("Delete this local draft?").setNegativeButton("Cancel",null).setPositiveButton("Delete",(d,x)->{try{EightPimStore.delete(store,EightPimModels.DRAFTS,p.optString("id"));if(id.equals(p.optString("id")))clear();drafts();}catch(JSONException e){EightAppUi.error(activity,e);}}).show();return true;});content.addView(list);}
    void load(JSONObject row){id=row.optString("id",UUID.randomUUID().toString());for(Map.Entry<String,EditText> f:fields.entrySet())f.getValue().setText(row.optString(f.getKey()));attachments.clear();JSONArray links=row.optJSONArray("attachments");if(links!=null)for(int i=0;i<links.length();i++)if(links.optString(i).startsWith("content://"))attachments.add(Uri.parse(links.optString(i)));attachmentStatus();}
    void attachmentStatus(){if(status!=null)status.setText(attachments.size()+" attachment"+(attachments.size()==1?"":"s")+" · Drafts stay local; confirm sending in your email app.");}
    void pick(){if(!save(false))return;store.prefs.edit().putString("eight_mail_attachment_draft",id).apply();try{activity.startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION),PICK);}catch(RuntimeException e){EightAppUi.error(activity,e);}}
    void result(Intent data){if(data==null)return;Set<Uri> found=new LinkedHashSet<>();if(data.getClipData()!=null)for(int i=0;i<Math.min(10,data.getClipData().getItemCount());i++)found.add(data.getClipData().getItemAt(i).getUri());else if(data.getData()!=null)found.add(data.getData());int skipped=0;for(Uri u:found){if(attachments.contains(u))continue;if(attachments.size()>=10||!"content".equals(u.getScheme())){skipped++;continue;}if(EightFileGrants.keep(activity,u))attachments.add(u);else skipped++;}attachmentStatus();if(skipped>0)status.append(" Some files could not keep read access; choose them again from another provider.");}
    static Intent sendIntent(JSONObject row)throws JSONException{String uri=EightPimModels.mailto(row);JSONArray files=row.optJSONArray("attachments");Intent intent;if(files==null||files.length()==0)intent=new Intent(Intent.ACTION_SENDTO,Uri.parse(uri));else{ArrayList<Uri> links=new ArrayList<>();ClipData clip=null;for(int i=0;i<files.length();i++){Uri u=Uri.parse(files.getString(i));if(!"content".equals(u.getScheme()))throw new JSONException("Invalid attachment");links.add(u);if(clip==null)clip=ClipData.newRawUri("Mail attachment",u);else clip.addItem(new ClipData.Item(u));}intent=new Intent(links.size()>1?Intent.ACTION_SEND_MULTIPLE:Intent.ACTION_SEND).setType("message/rfc822").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);if(links.size()>1)intent.putParcelableArrayListExtra(Intent.EXTRA_STREAM,links);else intent.putExtra(Intent.EXTRA_STREAM,links.get(0));intent.setClipData(clip);}
        intent.putExtra(Intent.EXTRA_EMAIL,EightPimModels.recipients(row.optString("to"),true).split(",")).putExtra(Intent.EXTRA_CC,EightPimModels.recipients(row.optString("cc"),false).split(",")).putExtra(Intent.EXTRA_BCC,EightPimModels.recipients(row.optString("bcc"),false).split(",")).putExtra(Intent.EXTRA_SUBJECT,row.optString("subject")).putExtra(Intent.EXTRA_TEXT,row.optString("body"));return intent;}
    void send(){try{JSONObject row=EightPimModels.clean(EightPimModels.DRAFTS,draft());Intent intent=sendIntent(row);for(Uri uri:attachments)try(android.os.ParcelFileDescriptor file=activity.getContentResolver().openFileDescriptor(uri,"r")){if(file==null)throw new java.io.IOException();}catch(Exception e){throw new JSONException("An attachment is unavailable. Clear attachments and choose it again.");}if(!save(false))return;if(EightAppUi.launch(activity,Intent.createChooser(intent,"Choose an email app; confirm sending there")))status.setText("Opened an email app. This local draft is kept until you delete it.");}catch(JSONException e){fields.get("to").setError(e.getMessage());}}
    void inbox(){String pkg=store.prefs.getString("eight_mail_package","");Intent intent=pkg.isEmpty()?null:activity.getPackageManager().getLaunchIntentForPackage(pkg);if(intent!=null){EightAppUi.launch(activity,intent);return;}Intent category=new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_APP_EMAIL);if(!EightAppUi.launch(activity,Intent.createChooser(category,"Open your email inbox")))chooseApp();}
    void chooseApp(){List<ResolveInfo> found=activity.getPackageManager().queryIntentActivities(new Intent(Intent.ACTION_SENDTO,Uri.parse("mailto:")),0);LinkedHashMap<String,String> names=new LinkedHashMap<>();for(ResolveInfo r:found)if(activity.getPackageManager().getLaunchIntentForPackage(r.activityInfo.packageName)!=null)names.put(r.activityInfo.packageName,r.loadLabel(activity.getPackageManager()).toString());List<String> packages=new ArrayList<>(names.keySet());if(packages.isEmpty()){Aero.dialog(activity).setTitle("Mail app").setMessage("Install an Android email app, or choose Webmail. Nth keeps your local drafts.").setPositiveButton("OK",null).show();return;}Aero.dialog(activity).setTitle("Choose inbox app").setItems(names.values().toArray(new String[0]),(d,n)->{store.prefs.edit().putString("eight_mail_package",packages.get(n)).apply();inbox();}).show();}
    void webmail(){String[] labels={"Outlook","Gmail","Yahoo Mail","Proton Mail"},urls={"https://outlook.live.com/mail/","https://mail.google.com/mail/","https://mail.yahoo.com/","https://mail.proton.me/"};Aero.dialog(activity).setTitle("Open webmail in Nth Internet Explorer").setItems(labels,(d,n)->{if(keep())open.accept("eight-url:"+Uri.encode(urls[n]));}).show();}
    JSONObject state(){JSONObject s=new JSONObject();GadgetLayout.put(s,"draft",draft());GadgetLayout.put(s,"listing",listing);return s;}void restore(JSONObject s){if(s==null)return;JSONObject d=s.optJSONObject("draft");if(d!=null)load(d);if(s.optBoolean("listing"))drafts();else compose();}
    void close(){if(nonempty()&&(!(activity instanceof MainActivity)||!((MainActivity)activity).restoringLocalData()))save(false);}
}
